#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_table_is_sorted_so_a_lookup_can_be_a_binary_search() {
        for locale in &ALL {
            for pair in locale.entries.windows(2) {
                assert!(pair[0].0 < pair[1].0, "{} is out of order", locale.tag);
            }
            assert!(!locale.entries.is_empty(), "{}", locale.tag);
        }
    }

    #[test]
    fn no_index_is_past_the_english_table() {
        for locale in &ALL {
            for (position, _) in locale.entries {
                assert!(
                    (*position as usize) < crate::text_gen::ALL.len(),
                    "{} names position {position}",
                    locale.tag,
                );
            }
        }
    }

    #[test]
    fn the_tags_are_unique_and_find_agrees_with_the_list() {
        let mut tags: Vec<&str> = ALL.iter().map(|locale| locale.tag).collect();
        let count = tags.len();
        tags.sort_unstable();
        tags.dedup();
        assert_eq!(count, tags.len(), "two locales share a tag");
        for locale in &ALL {
            assert_eq!(find(locale.tag).map(|found| found.tag), Some(locale.tag));
        }
        assert!(find("xx-XX").is_none());
    }
}
